import{_ as n,c as i,o as t,ae as r}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"STRENGTHENING AND UNLEASHING AMERICA’S LAW ENFORCEMENT TO PURSUE CRIMINALS AND PROTECT INNOCENT CITIZENS","description":"","frontmatter":{"title":"STRENGTHENING AND UNLEASHING AMERICA’S LAW ENFORCEMENT TO PURSUE CRIMINALS AND PROTECT INNOCENT CITIZENS","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/strengthening-and-unleashing-americas-law-enforcement-to-pursue-criminals-and-protect-innocent-citizens/","publishDate":"2025-04-28T18:34:59-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-28-strengthening-and-unleashing-americas-law-enforcement-to-pursue-criminals-and-protect-innocent-citizens.md","filePath":"executive-orders/2025-04-28-strengthening-and-unleashing-americas-law-enforcement-to-pursue-criminals-and-protect-innocent-citizens.md"}'),a={name:"executive-orders/2025-04-28-strengthening-and-unleashing-americas-law-enforcement-to-pursue-criminals-and-protect-innocent-citizens.md"};function o(l,e,s,c,u,d){return t(),i("div",null,e[0]||(e[0]=[r('<h1 id="strengthening-and-unleashing-america-s-law-enforcement-to-pursue-criminals-and-protect-innocent-citizens" tabindex="-1">STRENGTHENING AND UNLEASHING AMERICA’S LAW ENFORCEMENT TO PURSUE CRIMINALS AND PROTECT INNOCENT CITIZENS <a class="header-anchor" href="#strengthening-and-unleashing-america-s-law-enforcement-to-pursue-criminals-and-protect-innocent-citizens" aria-label="Permalink to &quot;STRENGTHENING AND UNLEASHING AMERICA’S LAW ENFORCEMENT TO PURSUE CRIMINALS AND PROTECT INNOCENT CITIZENS&quot;">​</a></h1><p>Published: Monday, April 28, 2025</p><ul><li><p><strong>Commitment to Law Enforcement</strong>:</p><ul><li>Empower State and local law enforcement to combat criminal behavior.</li><li>Create an environment where citizens can safely enjoy their communities.</li></ul></li><li><p><strong>Challenges to Law Enforcement</strong>:</p><ul><li>Address issues arising from local leaders who hinder law enforcement effectiveness, leading to increased crime.</li></ul></li><li><p><strong>Administrative Actions</strong>:</p><ul><li>Establish best practices for local police forces.</li><li>Protect law enforcement officers from wrongful accusations.</li><li>Provide resources to officers in need.</li></ul></li><li><p><strong>Attorney General Mandates</strong>:</p><ul><li>Create a mechanism for legal resources and indemnification for officers facing unjust expenses.</li><li>Maximize Federal support for State and local law enforcement, including: <ul><li>New policing best practices.</li><li>Improved training quality.</li><li>Increased pay and benefits.</li><li>Enhanced legal protections.</li><li>Strengthened penalties for crimes against officers.</li><li>Investment in prison security.</li><li>Enhanced crime data collection and distribution.</li></ul></li><li>Review and modify Federal consent decrees that hinder law enforcement.</li></ul></li><li><p><strong>Military and National Security Support</strong>:</p><ul><li>Increase provision of military and national security assets to local law enforcement.</li><li>Develop effective use of these resources, training, and personnel for crime prevention.</li></ul></li><li><p><strong>Enforcement of Criminal Rights</strong>:</p><ul><li>Pursue legal remedies against state and local officials who obstruct law enforcement or violate civil rights under the guise of initiatives like diversity, equity, and inclusion.</li></ul></li><li><p><strong>Coordination with Homeland Security</strong>:</p><ul><li>Utilize Homeland Security Task Forces to advance objectives outlined in the order.</li></ul></li><li><p><strong>General Provisions</strong>:</p><ul><li>Order does not impair existing legal authority or the Office of Management and Budget functions.</li><li>Implementation is subject to law and appropriations.</li><li>No enforceable rights or benefits are created by this order.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/strengthening-and-unleashing-americas-law-enforcement-to-pursue-criminals-and-protect-innocent-citizens/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/strengthening-and-unleashing-americas-law-enforcement-to-pursue-criminals-and-protect-innocent-citizens/</a></p>',4)]))}const g=n(a,[["render",o]]);export{p as __pageData,g as default};
